import{_ as t,o,c as d,a2 as a}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"검색 문법","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/search-syntax.md","filePath":"ko-KR/user-guide/search-syntax.md","lastUpdated":1787649438000}'),c={name:"ko-KR/user-guide/search-syntax.md"};function l(s,e,i,n,r,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="검색-문법" tabindex="-1">검색 문법 <a class="header-anchor" href="#검색-문법" aria-label="Permalink to &quot;검색 문법&quot;">​</a></h1><p>Lertaro의 검색창은 단순한 텍스트 매칭을 뛰어넘는 강력한 검색 기능을 제공합니다. 초고속 검색 알고리즘을 바탕으로 퍼지(Fuzzy) 문자 도약 매칭, 논리 연산자, 단어 경계 수정자, 드라이브 및 경로 지정, 쿼리 토큰(Query Tokens)을 통한 2차 필터링 및 다국어 스마트 별칭을 지원하며, 모든 문법을 하나의 검색어 안에서 자유롭게 조합하여 사용할 수 있습니다.</p><h2 id="_1-기본-매칭-모드-및-대소문자-규칙" tabindex="-1">1. 기본 매칭 모드 및 대소문자 규칙 <a class="header-anchor" href="#_1-기본-매칭-모드-및-대소문자-규칙" aria-label="Permalink to &quot;1. 기본 매칭 모드 및 대소문자 규칙&quot;">​</a></h2><h3 id="퍼지-매칭-기본값" tabindex="-1">퍼지 매칭(기본값) <a class="header-anchor" href="#퍼지-매칭-기본값" aria-label="Permalink to &quot;퍼지 매칭(기본값)&quot;">​</a></h3><p>Lertaro는 기본적으로 퍼지 매칭(Fuzzy Matching)이 활성화되어 있습니다. 검색어의 각 문자가 파일 또는 폴더 이름 내에 순서대로 나타나기만 하면, 중간에 다른 문자가 섞여 있어도 정확하게 찾아냅니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">입력 예시</th><th style="text-align:left;">매칭 결과 예시</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ltro</code></td><td style="text-align:left;"><code>Lertaro.exe</code></td><td style="text-align:left;"><code>l</code> → <code>t</code> → <code>r</code> → <code>o</code> 순서로 도약 매칭 (<strong>L</strong>er<strong>t</strong>a<strong>ro</strong>.exe)</td></tr><tr><td style="text-align:left;"><code>vsc</code></td><td style="text-align:left;"><code>Visual Studio Code.lnk</code></td><td style="text-align:left;">각 단어의 첫 글자 매칭 (<strong>V</strong>isual <strong>S</strong>tudio <strong>C</strong>ode)</td></tr><tr><td style="text-align:left;"><code>rt-fin</code></td><td style="text-align:left;"><code>Q3-report-final.docx</code></td><td style="text-align:left;">연속된 부분 문자열 매칭 (Q3-repo<strong>rt-fin</strong>al.docx)</td></tr></tbody></table><p><strong>설정 → 일반 → 시스템 → 퍼지 매칭 활성화</strong> 옵션을 끄면, 연산자가 없는 일반 검색어는 연속된 부분 문자열로 매칭되어야 합니다(<code>abc</code>는 더 이상 <code>a-b-c</code>에 매칭되지 않음). 이 설정은 수정자가 없는 일반 단어에만 영향을 미치며, 아래에서 설명하는 모든 연산자의 동작은 동일하게 유지됩니다.</p><h3 id="스마트-대소문자-구분-smart-case" tabindex="-1">스마트 대소문자 구분(Smart Case) <a class="header-anchor" href="#스마트-대소문자-구분-smart-case" aria-label="Permalink to &quot;스마트 대소문자 구분(Smart Case)&quot;">​</a></h3><ul><li><strong>모두 소문자인 검색어</strong>: 기본적으로 대소문자를 구분하지 않습니다. 예를 들어 <code>myfile</code>은 <code>myfile</code>, <code>MyFile</code>, <code>MYFILE</code> 등을 모두 매칭합니다.</li><li><strong>대문자가 포함된 검색어</strong>: 단어에 대문자가 하나라도 포함되면 자동으로 <strong>대소문자를 엄격히 구분</strong>합니다. 예를 들어 <code>MyFile</code>은 <code>MyFile</code>만 매칭하며, 소문자 <code>myfile</code>은 매칭하지 않습니다.</li></ul><h2 id="_2-다중-검색어-및-논리-연산" tabindex="-1">2. 다중 검색어 및 논리 연산 <a class="header-anchor" href="#_2-다중-검색어-및-논리-연산" aria-label="Permalink to &quot;2. 다중 검색어 및 논리 연산&quot;">​</a></h2><h3 id="공백-and-그리고" tabindex="-1">공백: AND (그리고) <a class="header-anchor" href="#공백-and-그리고" aria-label="Permalink to &quot;공백: AND (그리고)&quot;">​</a></h3><p>여러 검색어를 공백으로 구분하면 모든 조건을 동시에 만족해야 합니다. 파일 이름 내에서 단어가 나타나는 순서는 <strong>상관없습니다</strong>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report final 2024</span></span></code></pre></div><p>위 입력은 <code>2024-Q3-report-final.docx</code>와 <code>final_report_2024.pdf</code> 모두에 매칭됩니다.</p><h3 id="파이프-or-또는" tabindex="-1">파이프 <code>|</code>: OR (또는) <a class="header-anchor" href="#파이프-or-또는" aria-label="Permalink to &quot;파이프 `|`: OR (또는)&quot;">​</a></h3><p>파이프 기호 <code>|</code>로 단어를 구분하면 둘 중 하나만 만족해도 결과에 포함됩니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>png | jpg | gif</span></span></code></pre></div><p>AND와 OR 논리를 자유롭게 조합할 수 있습니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report | summary 2024</span></span></code></pre></div><p>이는 <code>report</code> 또는 <code>summary</code>를 포함하고, 동시에 <code>2024</code>도 포함하는 파일을 검색합니다. OR 검색에서는 조건을 만족한 모든 단어가 결과 이름에서 동시에 강조 표시(하이라이트)됩니다.</p><h3 id="연산자-우선순위-or이-and보다-우선" tabindex="-1">연산자 우선순위: OR이 AND보다 우선 <a class="header-anchor" href="#연산자-우선순위-or이-and보다-우선" aria-label="Permalink to &quot;연산자 우선순위: OR이 AND보다 우선&quot;">​</a></h3><p>하나의 검색어 안에 공백(AND)과 파이프 <code>|</code>(OR)를 함께 사용하면, <code>|</code>의 우선순위가 공백보다 <strong>높습니다</strong>. <code>|</code> 양쪽의 단어가 먼저 하나의 OR 그룹으로 합쳐지고, 공백으로 구분된 그룹끼리 AND로 결합됩니다. 괄호는 지원되지 않으므로 이 결합 순서를 바꿀 수 없습니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report | summary 2024 | draft</span></span></code></pre></div><p>이는 <code>(report OR summary) AND (2024 OR draft)</code>와 동일합니다.</p><p>참고: <code>|</code>는 양쪽에 공백이 있는 독립된 단어여야 하며, <code>a|b</code>나 <code>a |b</code>는 OR로 해석되지 않습니다. 또한 <code>!</code> 제외어를 <code>|</code>의 OR 그룹 안에 넣지 마세요(예: <code>b | !c</code>). 이는 &quot;b가 일치하거나 c가 일치하지 않음&quot;으로 해석됩니다. 단어를 전체적으로 제외하려면 공백으로 구분된 독립된 AND 조건으로 지정하세요(예: <code>b !c</code>).</p><h3 id="단어-내-공백-및-따옴표-구문" tabindex="-1">단어 내 공백 및 따옴표 구문 <a class="header-anchor" href="#단어-내-공백-및-따옴표-구문" aria-label="Permalink to &quot;단어 내 공백 및 따옴표 구문&quot;">​</a></h3><p>공백이 포함된 구문 자체를 하나의 검색어로 다루려면 역슬래시로 공백을 이스케이프(<code>\\ </code>)하거나, 작은따옴표 <code>&#39;...&#39;</code> 또는 큰따옴표 <code>&quot;...&quot;</code>로 감싸서 입력합니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>final\\ report</span></span>\n<span class="line"><span>&#39;final report&#39;</span></span></code></pre></div><p>두 입력 방식 모두 <code>final report</code>를 두 개의 독립된 AND 단어가 아닌 공백이 포함된 하나의 완전한 구문으로 검색합니다.</p><h3 id="여러-줄-텍스트-붙여넣기-시-자동으로-or-변환" tabindex="-1">여러 줄 텍스트 붙여넣기 시 자동으로 OR 변환 <a class="header-anchor" href="#여러-줄-텍스트-붙여넣기-시-자동으로-or-변환" aria-label="Permalink to &quot;여러 줄 텍스트 붙여넣기 시 자동으로 OR 변환&quot;">​</a></h3><p>스프레드시트, 텍스트 파일, 로그 등에서 여러 줄의 텍스트(한 줄에 파일명 하나씩)를 복사하여 검색창에 붙여넣으면, Lertaro가 자동으로 각 줄을 <code>|</code>로 연결하여 하나의 OR 검색어로 변환합니다(빈 줄은 자동 제외).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123</span></span>\n<span class="line"><span>456</span></span>\n<span class="line"><span>678</span></span></code></pre></div><p>붙여넣으면 다음과 같이 자동 변환됩니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123 | 456 | 678</span></span></code></pre></div><h2 id="_3-검색-연산자-요약표" tabindex="-1">3. 검색 연산자 요약표 <a class="header-anchor" href="#_3-검색-연산자-요약표" aria-label="Permalink to &quot;3. 검색 연산자 요약표&quot;">​</a></h2><h3 id="연산자-표" tabindex="-1">연산자 표 <a class="header-anchor" href="#연산자-표" aria-label="Permalink to &quot;연산자 표&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">연산자 / 문법</th><th style="text-align:left;">유형</th><th style="text-align:left;">효과 설명</th><th style="text-align:left;">입력 예시</th><th style="text-align:left;">매칭 결과 예시</th></tr></thead><tbody><tr><td style="text-align:left;"><em>(없음)</em></td><td style="text-align:left;">기본 퍼지</td><td style="text-align:left;">문자가 순서대로 나타나면 매칭 (퍼지 켜짐 시)</td><td style="text-align:left;"><code>report</code></td><td style="text-align:left;"><code>Q3-report-final.docx</code></td></tr><tr><td style="text-align:left;"><code>!</code></td><td style="text-align:left;">제외</td><td style="text-align:left;">해당 부분 문자열이 정확히 포함된 모든 결과 제외</td><td style="text-align:left;"><code>!temp</code></td><td style="text-align:left;"><code>temp</code>가 포함된 파일 필터링 제외</td></tr><tr><td style="text-align:left;"><code>&#39;</code></td><td style="text-align:left;">정확도 반전</td><td style="text-align:left;">퍼지 켜짐 시 정확한 부분 매칭, 퍼지 꺼짐 시 퍼지 매칭</td><td style="text-align:left;"><code>&#39;report</code></td><td style="text-align:left;">연속된 <code>report</code> 문자열이 반드시 포함되어야 함</td></tr><tr><td style="text-align:left;"><code>&#39;...&#39;</code></td><td style="text-align:left;">단어 경계 매칭</td><td style="text-align:left;">단어 경계에서 정확히 일치 (단어 중간 부분 오일치 방지)</td><td style="text-align:left;"><code>&#39;app&#39;</code></td><td style="text-align:left;"><code>app.exe</code>, <code>my-app.log</code> 매칭, <code>whatsapp.exe</code> 불일치</td></tr><tr><td style="text-align:left;"><code>^</code></td><td style="text-align:left;">접두사 매칭</td><td style="text-align:left;">파일/폴더 이름이 해당 문자로 시작해야 함</td><td style="text-align:left;"><code>^IMG</code></td><td style="text-align:left;"><code>IMG_20240101.jpg</code> (<code>MY_IMG.jpg</code> 불일치)</td></tr><tr><td style="text-align:left;"><code>$</code></td><td style="text-align:left;">접미사 매칭</td><td style="text-align:left;">파일/폴더 이름이 해당 문자로 끝나야 함</td><td style="text-align:left;"><code>.pdf$</code></td><td style="text-align:left;"><code>document.pdf</code> (<code>document.pdf.bak</code> 불일치)</td></tr><tr><td style="text-align:left;"><code>^...$</code></td><td style="text-align:left;">완전 일치</td><td style="text-align:left;">이름 전체가 해당 문자와 정확히 일치해야 함</td><td style="text-align:left;"><code>^readme.md$</code></td><td style="text-align:left;"><code>readme.md</code>에만 정확히 일치</td></tr><tr><td style="text-align:left;"><code>|</code></td><td style="text-align:left;">OR 논리</td><td style="text-align:left;">파이프 기호 양쪽 조건 중 하나 이상 만족</td><td style="text-align:left;"><code>doc | pdf</code></td><td style="text-align:left;"><code>doc</code> 또는 <code>pdf</code>가 포함된 이름 매칭</td></tr></tbody></table><h3 id="연산자-심화-설명-및-실전-조합" tabindex="-1">연산자 심화 설명 및 실전 조합 <a class="header-anchor" href="#연산자-심화-설명-및-실전-조합" aria-label="Permalink to &quot;연산자 심화 설명 및 실전 조합&quot;">​</a></h3><ol><li><strong>제외 수정자 <code>!</code></strong>: <code>!term</code>은 <code>term</code> 부분 문자열을 포함하는 결과를 즉시 제외합니다. 무고한 파일이 누락되지 않도록 제외 항목에는 병음/별칭 확장이 적용되지 않습니다.</li><li><strong>정확도 반전 <code>&#39;</code></strong>: 전체 퍼지 매칭이 켜진 상태에서 검색어 앞에 <code>&#39;</code>를 붙이면 해당 단어만 연속된 정확한 부분 문자열로 검색됩니다. <ul><li>예를 들어 <code>lertaro &#39;v1.2</code>는 <code>lertaro</code>는 퍼지로, <code>v1.2</code>는 정확한 연속 문자로 찾습니다.</li><li>정확 검색이어도 병음 별칭이 있는 파일 이름은 계속 매칭됩니다. 예를 들어 <code>&#39;exe$</code>는 <code>古恩希尔</code>(병음이 <code>gexe</code>로 매핑됨)도 찾습니다.</li></ul></li><li><strong>단어 경계 일치 <code>&#39;...&#39;</code></strong>: 단어를 따옴표로 감싸면(예: <code>&#39;app&#39;</code>), 매칭 엔진이 앞뒤 경계(공백, 기호, 하이픈, 언더바, 문자열 끝)를 확인하여 긴 단어 중간에서 원치 않게 일치하는 현상을 방지합니다.</li><li><strong>완전 일치 <code>^...$</code></strong>: <code>^</code>와 <code>$</code>가 <strong>동일한 단어</strong>를 감싸고 있을 때만 작동합니다. 서로 다른 단어에 각각 지정된 경우(예: <code>^src md$</code>)에는 독립적인 접두사 및 접미사 필터로 작동합니다.</li></ol><p><strong>다중 연산자 조합 실전 예시</strong>:</p><ul><li><code>^IMG !.png$ 2024</code>: <code>IMG</code>로 시작하고 <code>2024</code>를 포함하며 확장자가 <code>.png</code>가 <strong>아닌</strong> 파일을 검색합니다.</li><li><code>&#39;data | &#39;backup ^2024 .zip$</code>: <code>2024</code>로 시작하고 <code>.zip</code>으로 끝나며, 이름에 <code>data</code> 또는 <code>backup</code>이 정확히 포함된 압축 파일을 검색합니다.</li><li><code>^report &#39;公告 | &#39;gw .pdf$ !draft</code>: 이름이 <code>report</code>로 시작하고 <code>.pdf</code>로 끝나며 <code>draft</code>를 포함하지 않고, 이름에 <code>公告</code>, <code>gw</code>, <code>公文</code> 또는 <code>gw</code> 병음에 해당하는 기타 문자열 조합이 정확히 포함된 파일을 검색합니다(<code>&#39;公告 | &#39;gw</code>가 하나의 OR 그룹을 이루며, 나머지 공백 조건과 AND로 결합됩니다).</li></ul><h2 id="_4-경로-모드-및-드라이브-범위-지정" tabindex="-1">4. 경로 모드 및 드라이브 범위 지정 <a class="header-anchor" href="#_4-경로-모드-및-드라이브-범위-지정" aria-label="Permalink to &quot;4. 경로 모드 및 드라이브 범위 지정&quot;">​</a></h2><h3 id="드라이브-지정" tabindex="-1">드라이브 지정 <a class="header-anchor" href="#드라이브-지정" aria-label="Permalink to &quot;드라이브 지정&quot;">​</a></h3><p>검색창 맨 앞에 드라이브 문자와 콜론을 입력하여 검색 범위를 특정 드라이브로 제한할 수 있습니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d: report</span></span></code></pre></div><p>공백은 생략 가능하며, <code>d:report</code>와 <code>d: report</code>는 동일합니다.</p><h3 id="전체-경로-모드" tabindex="-1">전체 경로 모드 <a class="header-anchor" href="#전체-경로-모드" aria-label="Permalink to &quot;전체 경로 모드&quot;">​</a></h3><p>검색어에 경로 구분 기호(<code>\\</code> 또는 <code>/</code>)가 포함되어 있으면 Lertaro가 자동으로 전체 경로 매칭 모드로 전환됩니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Projects\\Lertaro</span></span></code></pre></div><p>경로 구분 기호로 끝나는 경우(예: <code>D:\\Projects\\</code>) 해당 폴더 <strong>내부</strong>의 직속 항목들을 직접 검색합니다.</p><h3 id="상위-폴더-이름-대체-매칭-folder-matching" tabindex="-1">상위 폴더 이름 대체 매칭 (Folder Matching) <a class="header-anchor" href="#상위-폴더-이름-대체-매칭-folder-matching" aria-label="Permalink to &quot;상위 폴더 이름 대체 매칭 (Folder Matching)&quot;">​</a></h3><p>파일명 단독 검색으로 결과 목록 상한을 채우지 못한 경우, Lertaro는 파일명에 매칭되지 않은 나머지 검색어를 사용하여 상위 폴더 이름과의 매칭을 자동으로 보완합니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d01j dcj</span></span></code></pre></div><p><code>dcj</code>라는 문자열이 파일 자체의 이름에 없더라도, <code>dcj</code>라는 이름의 폴더 안에 있는 <code>d01j.txt</code> 파일을 찾아낼 수 있습니다.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>검색어 중 최소 하나는 파일명 자체와 일치해야 하며, 파일명 단독 매칭 결과가 부족할 때만 작동합니다. 보완된 결과는 항상 일반 검색 결과 뒤에 배치되므로 일반 결과의 순서를 방해하지 않습니다.</p></div><h2 id="_5-쿼리-토큰-및-2차-필터링-query-tokens" tabindex="-1">5. 쿼리 토큰 및 2차 필터링 (Query Tokens) <a class="header-anchor" href="#_5-쿼리-토큰-및-2차-필터링-query-tokens" aria-label="Permalink to &quot;5. 쿼리 토큰 및 2차 필터링 (Query Tokens)&quot;">​</a></h2><p>Lertaro는 기본 검색어 뒤에 콜론 <code>:</code>(<strong>설정 → 일반 → 시스템 → 쿼리 토큰 총 접두 문자</strong>에서 변경 가능)으로 시작하는 **쿼리 토큰(Query Tokens)**을 추가하여 1차 검색 결과를 정렬하거나 2차 필터링할 수 있습니다.</p><p>하나의 <code>:</code> 뒤에 쉼표 <code>,</code>로 구분하여 여러 토큰을 연쇄 결합할 수 있습니다(예: <code>report :@doc,M-,:-F</code>).</p><h3 id="파일-카테고리-필터-카테고리명" tabindex="-1">파일 카테고리 필터 (<code>:@&lt;카테고리명&gt;</code>) <a class="header-anchor" href="#파일-카테고리-필터-카테고리명" aria-label="Permalink to &quot;파일 카테고리 필터 (`:@&lt;카테고리명&gt;`)&quot;">​</a></h3><p>미리 정의된 확장자 카테고리 규칙을 빠르게 적용하며, <code>|</code>를 사용한 다중 지정도 가능합니다.</p><ul><li><code>:@doc</code>: 문서류 (<code>*.doc; *.docx; *.pdf; *.txt; *.ppt; *.pptx; *.xls; *.xlsx; *.csv; *.rtf; *.md; *.wps</code>)</li><li><code>:@img</code>: 이미지류 (<code>*.jpg; *.jpeg; *.png; *.gif; *.bmp; *.webp; *.ico; *.svg; *.tif; *.tiff; *.psd; *.ai</code>)</li><li><code>:@video</code>: 동영상류 (<code>*.mp4; *.mkv; *.avi; *.mov; *.wmv; *.flv; *.m4v; *.webm; *.3gp; *.rmvb; *.ts</code>)</li><li><code>:@audio</code>: 오디오류 (<code>*.mp3; *.wav; *.flac; *.aac; *.ogg; *.m4a; *.wma; *.ape</code>)</li><li><code>:@zip</code>: 압축 파일류 (<code>*.zip; *.rar; *.7z; *.tar; *.gz; *.bz2; *.xz; *.iso</code>)</li></ul><p><strong>예시</strong>:</p><ul><li><code>재무 :@doc</code>: 문서류에서 &quot;재무&quot; 검색.</li><li><code>배경화면 :@img</code>: 이미지 파일에서 &quot;배경화면&quot; 검색.</li><li><code>clip :@video|audio</code>: 동영상 또는 오디오 파일에서 &quot;clip&quot; 검색.</li></ul><p><strong>설정 → 플러그인 → CoreExtensions</strong>에서 카테고리 규칙을 수정하거나 새 카테고리를 추가할 수 있습니다.</p><h3 id="확장자-직접-지정-필터-ext-또는-ext1-ext2" tabindex="-1">확장자 직접 지정 필터 (<code>:.ext</code> 또는 <code>:.ext1.ext2</code>) <a class="header-anchor" href="#확장자-직접-지정-필터-ext-또는-ext1-ext2" aria-label="Permalink to &quot;확장자 직접 지정 필터 (`:.ext` 또는 `:.ext1.ext2`)&quot;">​</a></h3><p>점으로 시작하는 확장자를 직접 입력합니다(폴더는 자동 제외).</p><ul><li><code>report :.pdf</code>: <code>.pdf</code> 파일만 유지.</li><li><code>data :.csv.xlsx</code>: <code>.csv</code> 또는 <code>.xlsx</code> 스프레드시트 파일만 유지.</li></ul><h3 id="결과-정렬-및-파일-폴더-필터-scmaf" tabindex="-1">결과 정렬 및 파일/폴더 필터 (<code>:[SCMAF]</code>) <a class="header-anchor" href="#결과-정렬-및-파일-폴더-필터-scmaf" aria-label="Permalink to &quot;결과 정렬 및 파일/폴더 필터 (`:[SCMAF]`)&quot;">​</a></h3><p>단일 영문자로 속성을 지정합니다: <code>S</code>(크기/Size), <code>C</code>(생성일/Created), <code>M</code>(수정일/Modified), <code>A</code>(액세스일/Accessed), <code>F</code>(폴더/파일 필터).</p><p>기본 문자는 <strong>오름차순</strong>(작은 순 / 오래된 순)을 나타내며, 마이너스 <code>-</code> 기호(접두사 또는 접미사, 예: <code>M-</code> 또는 <code>:-M</code>)를 붙이면 <strong>내림차순</strong>(큰 순 / 최신 순) 또는 반전 필터링이 됩니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">토큰 문법</th><th style="text-align:left;">효과 설명</th><th style="text-align:left;">대표적인 활용 시나리오</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:S</code></td><td style="text-align:left;">파일 크기 오름차순 (가장 작은 파일 먼저)</td><td style="text-align:left;">빈 파일 또는 용량이 작은 파일 찾기</td></tr><tr><td style="text-align:left;"><code>:S-</code> 또는 <code>:-S</code></td><td style="text-align:left;">파일 크기 내림차순 (가장 큰 파일 먼저)</td><td style="text-align:left;"><code>log :S-</code> (용량을 많이 차지하는 대용량 로그 파일 찾기)</td></tr><tr><td style="text-align:left;"><code>:M</code></td><td style="text-align:left;">수정일 오름차순 (가장 오래된 수정 먼저)</td><td style="text-align:left;">오랫동안 수정되지 않은 파일 점검</td></tr><tr><td style="text-align:left;"><code>:M-</code> 또는 <code>:-M</code></td><td style="text-align:left;">수정일 내림차순 (최근 수정된 파일 먼저)</td><td style="text-align:left;"><code>report :M-</code> (최근 작업한 문서 빠르게 찾기)</td></tr><tr><td style="text-align:left;"><code>:C</code> / <code>:C-</code></td><td style="text-align:left;">생성일 오름차순 / 내림차순</td><td style="text-align:left;"><code>build :C-</code> (가장 최근에 생성된 빌드 파일 찾기)</td></tr><tr><td style="text-align:left;"><code>:A</code> / <code>:A-</code></td><td style="text-align:left;">액세스일 오름차순 / 내림차순</td><td style="text-align:left;"><code>project :A-</code> (최근에 열어본 프로젝트 찾기)</td></tr><tr><td style="text-align:left;"><code>:F</code></td><td style="text-align:left;"><strong>폴더만 표시</strong> (일반 파일 제외)</td><td style="text-align:left;"><code>config :F</code> (config라는 이름의 디렉토리만 찾기)</td></tr><tr><td style="text-align:left;"><code>:-F</code> 또는 <code>:F-</code></td><td style="text-align:left;"><strong>파일만 표시</strong> (폴더 제외)</td><td style="text-align:left;"><code>config :-F</code> (config라는 이름의 파일만 찾기)</td></tr></tbody></table><h3 id="와일드카드-2차-필터-패턴-또는-패턴" tabindex="-1">와일드카드 2차 필터 (<code>:?&lt;패턴&gt;</code> 또는 <code>?&lt;패턴&gt;</code>) <a class="header-anchor" href="#와일드카드-2차-필터-패턴-또는-패턴" aria-label="Permalink to &quot;와일드카드 2차 필터 (`:?&lt;패턴&gt;` 또는 `?&lt;패턴&gt;`)&quot;">​</a></h3><p>표준 Windows 와일드카드(<code>?</code>는 임의의 한 문자, <code>*</code>는 0개 이상의 문자)를 사용하여 정밀하게 필터링하며, <code>|</code>나 <code>;</code>로 여러 OR 조건을 지정할 수 있습니다.</p><ul><li><code>mp4 :?(2026???????????)</code>: <code>2026</code> 및 11자리 타임스탬프가 포함된 비디오 파일 매칭.</li><li><code>photo :?IMG_????.jpg|DSC_????.jpg</code>: 특정 카메라 형식의 사진 번호 매칭.</li></ul><h3 id="경로-부분-일치-필터-경로패턴" tabindex="-1">경로 부분 일치 필터 (<code>::&lt;경로패턴&gt;</code>) <a class="header-anchor" href="#경로-부분-일치-필터-경로패턴" aria-label="Permalink to &quot;경로 부분 일치 필터 (`::&lt;경로패턴&gt;`)&quot;">​</a></h3><p>상위 폴더 이름이나 파일명 자체에 지정된 퍼지 키워드가 포함되어야 합니다.</p><ul><li><code>report ::2024</code>: 파일이 위치한 상위 경로 어디에든 <code>2024</code>가 포함되어야 함.</li><li><code>main ::&quot;src\\core&quot;</code>: <code>src\\core</code> 하위 경로에 위치한 파일로 한정.</li></ul><h3 id="연쇄-토큰-결합-예시" tabindex="-1">연쇄 토큰 결합 예시 <a class="header-anchor" href="#연쇄-토큰-결합-예시" aria-label="Permalink to &quot;연쇄 토큰 결합 예시&quot;">​</a></h3><p>여러 토큰을 하나의 <code>:</code> 뒤에 결합하여 사용할 수 있습니다.</p><ul><li><code>재무보고서 :@doc,M-</code>: &quot;재무보고서&quot;를 검색하고, 문서류로 한정하며, 수정일 최신순으로 정렬.</li><li><code>backup :.zip,S-,:-F</code>: &quot;backup&quot;을 검색하고, <code>.zip</code> 압축 파일로 한정하며, 크기가 큰 순서대로 파일만 표시.</li><li><code>icon ::assets,?*128*</code>: &quot;icon&quot;을 검색하고, 경로에 <code>assets</code>가 포함되며 파일명에 <code>128</code> 크기 표시가 있는 항목만 필터링.</li></ul><h2 id="_6-특수-검색-기능" tabindex="-1">6. 특수 검색 기능 <a class="header-anchor" href="#_6-특수-검색-기능" aria-label="Permalink to &quot;6. 특수 검색 기능&quot;">​</a></h2><h3 id="_1회성-검색에서-제외-규칙-임시-무시" tabindex="-1">1회성 검색에서 제외 규칙 임시 무시 <a class="header-anchor" href="#_1회성-검색에서-제외-규칙-임시-무시" aria-label="Permalink to &quot;1회성 검색에서 제외 규칙 임시 무시&quot;">​</a></h3><p>검색어 맨 앞에 <code>*</code>를 붙이면 <a href="./settings/index-drives.html#제외-규칙"><strong>제외 규칙</strong></a>에 설정된 경로 제외, Glob, 정규식을 이번 검색에 한해 임시로 무시하고 검색할 수 있습니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*node_modules</span></span></code></pre></div><p>맨 앞의 <code>*</code>는 매칭 전에 자동으로 제거됩니다. 이미 인덱싱된 항목만 찾을 수 있으며(네트워크나 WSL에서 아예 스캔되지 않은 폴더는 나타나지 않음), 시스템 숨김 파일 필터링 등은 그대로 유지됩니다.</p><h3 id="결과-유형-트리거" tabindex="-1">결과 유형 트리거 <a class="header-anchor" href="#결과-유형-트리거" aria-label="Permalink to &quot;결과 유형 트리거&quot;">​</a></h3><p><strong>설정 → 일반 → 퀵 검색창 → 결과 유형 우선순위</strong>에서 특정 결과 유형(응용 프로그램, 시스템 설정, 파일 카테고리, 플러그인 항목, 일반 파일 등)에 1글자의 <strong>트리거 문자</strong>를 할당할 수 있습니다.</p><p>퀵 검색창 맨 앞에 해당 트리거 문자를 입력하면 해당 유형의 결과만 표시되고 다른 유형은 모두 숨겨집니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;vs</span></span></code></pre></div><p>예를 들어 <code>;</code>가 &quot;응용 프로그램&quot;에 할당되어 있다면, 위 입력은 응용 프로그램 중에서만 Visual Studio를 검색합니다. 퀵 창과 인라인 창에서는 트리거와 무관하게 히스토리와 즐겨찾기가 항상 최상단에 고정 표시됩니다.</p><h2 id="_7-다국어-스마트-별칭" tabindex="-1">7. 다국어 스마트 별칭 <a class="header-anchor" href="#_7-다국어-스마트-별칭" aria-label="Permalink to &quot;7. 다국어 스마트 별칭&quot;">​</a></h2><h3 id="중국어-파일명-병음-별칭" tabindex="-1">중국어 파일명: 병음 별칭 <a class="header-anchor" href="#중국어-파일명-병음-별칭" aria-label="Permalink to &quot;중국어 파일명: 병음 별칭&quot;">​</a></h3><p>기본 내장된 병음 별칭 플러그인(<code>PinyinAlias</code>)을 통해 설정 없이도 로마자 병음으로 중국어 파일명을 검색할 수 있습니다.</p><ul><li><strong>전체 병음</strong>: <code>chongqing</code>을 입력하여 <code>重庆.docx</code> 매칭.</li><li><strong>초성 / 이니셜</strong>: <code>cq</code>를 입력하여 <code>重庆.docx</code> 매칭, <code>wzry</code>로 <code>王者荣耀.exe</code> 매칭.</li><li><strong>다음자(다양한 발음) 지원</strong>: 여러 발음을 가진 한자도 자주 쓰이는 독음으로 자동 인덱싱됩니다.</li></ul><p><strong>설정 → 플러그인</strong>에서 <code>PinyinAlias</code> 플러그인의 활성화 여부를 확인할 수 있습니다.</p><h3 id="스페인어-파일명-악센트-별칭" tabindex="-1">스페인어 파일명: 악센트 별칭 <a class="header-anchor" href="#스페인어-파일명-악센트-별칭" aria-label="Permalink to &quot;스페인어 파일명: 악센트 별칭&quot;">​</a></h3><p>내장된 <code>SpanishAlias</code> 플러그인을 통해 악센트 문자(<code>á</code>, <code>é</code>, <code>í</code>, <code>ó</code>, <code>ú</code>, <code>ü</code>, <code>ñ</code>)가 포함된 파일명을 일반 ASCII 문자로 원활하게 검색할 수 있습니다.</p><ul><li><code>cancion</code>으로 <code>Canción.mp3</code> 매칭.</li><li><code>nino</code>로 <code>Niño.txt</code> 매칭.</li><li><code>ciguena</code>로 <code>Cigüeña.png</code> 매칭.</li></ul><p>일치한 문자(원래 파일명의 악센트 문자 포함)가 정확하게 하이라이트됩니다.</p><h2 id="_8-자주-묻는-질문-및-즐겨찾기" tabindex="-1">8. 자주 묻는 질문 및 즐겨찾기 <a class="header-anchor" href="#_8-자주-묻는-질문-및-즐겨찾기" aria-label="Permalink to &quot;8. 자주 묻는 질문 및 즐겨찾기&quot;">​</a></h2><h3 id="즐겨찾기-커스텀-별칭이-아닙니다" tabindex="-1">즐겨찾기, 커스텀 별칭이 아닙니다 <a class="header-anchor" href="#즐겨찾기-커스텀-별칭이-아닙니다" aria-label="Permalink to &quot;즐겨찾기, 커스텀 별칭이 아닙니다&quot;">​</a></h3><p>Lertaro는 범용적인 &quot;사용자 지정 검색 별칭/매크로&quot; 시스템을 별도로 두지 않습니다. 가장 가까운 기본 기능은 <a href="./settings/favorites.html"><strong>즐겨찾기</strong></a>입니다. 원하는 파일, 폴더, 웹 URL을 커스텀 표시 이름으로 즐겨찾기에 등록하면 해당 이름으로 즉시 검색할 수 있습니다(결과에 ★ 아이콘 표시).</p><p>특정 키워드로 프로그램을 실행하거나 스크립트를 호출하려면 <a href="./instant-answers.html#커스텀-명령어"><strong>커스텀 명령어</strong></a>를 참조하세요.</p>',103)])])}const u=t(c,[["render",l]]);export{g as __pageData,u as default};
